package de.lazytv.pro.catalog;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class HttpClient { private HttpClient(){} public static String get(String u,Map<String,String> headers)throws CatalogException{HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(true);c.setRequestProperty("User-Agent","LazyTV-PRO/1.0");if(headers!=null)for(Map.Entry<String,String>e:headers.entrySet())c.setRequestProperty(e.getKey(),e.getValue());int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();String body=read(in);if(code==401||code==403)throw new CatalogException("Credentials/refuzim nga serveri (HTTP "+code+")");if(code<200||code>=300)throw new CatalogException("Serveri ktheu HTTP "+code);return body;}catch(SocketTimeoutException e){throw new CatalogException("Serveri nuk u përgjigj brenda afatit",e);}catch(CatalogException e){throw e;}catch(Exception e){throw new CatalogException("Serveri nuk mund të arrihet",e);}finally{if(c!=null)c.disconnect();}}private static String read(InputStream in)throws IOException{if(in==null)return"";try(BufferedReader b=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){StringBuilder s=new StringBuilder();char[] x=new char[8192];int n;while((n=b.read(x))!=-1){s.append(x,0,n);if(s.length()>25_000_000)throw new IOException("Përgjigjja është shumë e madhe");}return s.toString();}}public static String enc(String s){try{return URLEncoder.encode(s==null?"":s,"UTF-8");}catch(Exception e){return"";}}}
